UPDATE party_word_bank AS bank
SET clues=corrections.clues, version=bank.version+1, updated_at=now()
FROM corrections
WHERE bank.id=corrections.id AND bank.answer=corrections.answer
  AND bank.category=corrections.category AND bank.clues=corrections.previous_clues;
